import {keys,scale,totals,localDate,weightTrend,averageWeight} from './core.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blank=()=>({version:1,days:{},customFoods:[],recipes:[],profile:{name:'Nikhil',diet:'vegetarian',goal:'Build strength & lose fat',targets:{kcal:2000,protein:100,fat:65,carbs:250,fiber:30,sleep:8,exercise:30}},revision:0,pending:true});
let state;try{state=JSON.parse(localStorage.getItem('sprout-v1'))||blank();}catch{state=blank();}
let syncing=false,syncTimer;
let foods=[],tab='today',date=localDate(),search='',filter=state.profile.diet,token=null,recipeDraft=[],storageAvailable=true;
const names={kcal:'Calories',protein:'Protein',fat:'Fat',carbs:'Carbs',fiber:'Fiber'};
const colors={protein:'#9bc779',fat:'#eac06a',carbs:'#94b2d6',fiber:'#c0a3d6',kcal:'#91ad68'};
const day=()=>state.days[date]||{meals:[],weight:null,sleep:null,exercise:[]};
const exerciseMinutes=d=>(d.exercise||[]).reduce((s,e)=>s+e.minutes,0);
const n=v=>Number(v||0).toLocaleString(undefined,{maximumFractionDigits:1});
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function persist(){state.pending=true;state.eventId=crypto.randomUUID();try{localStorage.setItem('sprout-v1',JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;notify('Device storage is unavailable. Export JSON to keep your entries.');}updateStatus();if(token){clearTimeout(syncTimer);syncTimer=setTimeout(sync,1200);}}
function updateStatus(){$('#save-status').textContent=!storageAvailable?'Not saved — export JSON':state.pending?'Saved here · cloud pending':'Cloud synced';}
function editDay(fn){const d=structuredClone(day());fn(d);state.days[date]=d;persist();render();}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
function close(){$('#modal').close();}
$('.close').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close();});
$('#day').value=date;$('#day').max=localDate();$('#day').onchange=e=>{if(e.target.value&&e.target.value<=localDate()){date=e.target.value;render();}};
function navigate(t){tab=t;render();}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>navigate(b.dataset.tab));$('#profile-button').onclick=()=>navigate('settings');
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#date-label').textContent=new Date(date+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase();$('#page-title').innerHTML=({today:'Make today count',food:'Good food. Good fuel',progress:'Look how far you’ve come',settings:'Make it yours'}[tab])+'<span>.</span>';$('#profile-button').textContent=state.profile.name.slice(0,1);({today:renderToday,food:renderFood,progress:renderProgress,settings:renderSettings}[tab])();updateStatus();}
function renderToday(){const d=day(),t=totals(d.meals),g=state.profile.targets,min=exerciseMinutes(d),trend=weightTrend(state.days,date);const quests=[{done:d.meals.length>0,title:'Fuel your day',detail:'Log a meal, however simple.',action:'food'},{done:d.weight!=null,title:'Check in with yourself',detail:'A weight entry is a data point, not a verdict.',action:'weight'},{done:min>=g.exercise,title:'Find your kind of movement',detail:`${n(min)} / ${g.exercise} minutes logged`,action:'exercise'}];const count=quests.filter(q=>q.done).length;
$('#content').innerHTML=`<div class="top-grid"><section class="journey"><div class="journey-copy"><span class="pill">✦ ${count} of 3 daily quests</span><h2>A little better.<br>Every single day.</h2><p>${esc(state.profile.name)}, your next small win starts right here.</p><button class="primary" id="log-meal">+ Log a meal</button></div><img class="avatar" src="assets/companion.png" alt="Your friendly fitness companion holding a dumbbell"></section><section class="card"><div class="card-head"><h2>Daily energy</h2><small>kcal</small></div><div class="energy-body"><div class="ring" style="--angle:${Math.min(360,t.kcal/g.kcal*360)}deg"><div class="ring-text"><strong>${n(t.kcal)}</strong><small>of ${n(g.kcal)} kcal</small></div></div><div class="energy-details"><p>${t.kcal>g.kcal?'ABOVE TARGET':'REMAINING'}</p><b>${n(Math.abs(g.kcal-t.kcal))} <small>kcal</small></b><hr><p>MEALS LOGGED</p><b>${d.meals.length}</b></div></div><p class="hint">${t.missing.includes('kcal')?'Some foods are missing energy values. Total is partial.':'Your editable target · exercise calories are not deducted.'}</p></section></div><div class="section-heading"><h2>Your daily essentials</h2><button class="text-button" id="edit-targets">Edit targets</button></div><div class="macros">${['protein','carbs','fat','fiber'].map(k=>`<div class="macro"><div class="macro-top"><span>${names[k]}</span><span style="color:${colors[k]}">◈</span></div><strong>${n(t[k])}<small> g</small></strong> <small>/ ${g[k]} g${t.missing.includes(k)?' · partial':''}</small><div class="bar"><span style="width:${Math.min(100,t[k]/g[k]*100)}%;--color:${colors[k]}"></span></div></div>`).join('')}<div class="macro"><div class="macro-top"><span>Movement</span><span>↗</span></div><strong>${n(min)}<small> min</small></strong> <small>/ ${g.exercise}</small><div class="bar"><span style="width:${Math.min(100,min/g.exercise*100)}%"></span></div></div></div><div class="checkins"><button class="checkin" data-check="weight"><span>◉ &nbsp; BODY WEIGHT</span><strong>${d.weight==null?'Add weight':n(d.weight)+' kg'}</strong><small>${trend&&trend.to===date?`${Math.abs(trend.delta)<0.05?'Steady':trend.delta>0?'↑ Gained':'↓ Lost'} ${n(Math.abs(trend.delta))} kg since ${trend.from}`:'Build your personal baseline'} · +</small></button><button class="checkin" data-check="sleep"><span>☾ &nbsp; LAST NIGHT’S SLEEP</span><strong>${d.sleep==null?'Log sleep':n(d.sleep)+' hours'}</strong><small>Your target: ${g.sleep} hours · +</small></button><button class="checkin" data-check="exercise"><span>↗ &nbsp; EXERCISE</span><strong>${min?min+' minutes':'Add movement'}</strong><small>Every kind of movement counts · +</small></button></div><div class="lower-grid"><section class="card"><div class="card-head"><h2>On your plate</h2><button class="text-button" id="add-food">+ Add food</button></div>${d.meals.length?d.meals.map((m,i)=>`<div class="meal-row"><span class="meal-icon">◈</span><div class="meal-info"><b>${esc(m.name)}</b><small>${esc(m.meal)} · ${n(m.grams)} g · ${m.nutrients.protein==null?"—":n(m.nutrients.protein)} g protein</small></div><span class="meal-kcal">${m.nutrients.kcal==null?'—':n(m.nutrients.kcal)}</span><button class="text-button" data-edit="${i}" aria-label="Edit ${esc(m.name)}">Edit</button><button class="text-button danger" data-delete="${i}" aria-label="Delete ${esc(m.name)}">×</button></div>`).join(''):`<div class="meal-empty"><div class="empty-symbol">◈</div><h3>A fresh plate. A fresh start.</h3><p>Find your food, dial in the portion,<br>and let the numbers take care of themselves.</p><button class="secondary" id="browse-food">Explore food studio</button></div>`}</section><section class="card"><div class="card-head"><h2>Today’s little wins</h2><span class="tag">${count}/3 complete</span></div>${quests.map(q=>`<div class="quest ${q.done?'complete':''}"><span class="quest-icon">${q.done?'✓':'○'}</span><div><b>${q.title}</b><p>${q.detail}</p></div><button class="text-button" data-quest="${q.action}">${q.done?'Edit':'Start'}</button></div>`).join('')}</section></div><div class="insight"><span>✦</span><div><b>A thought for today</b><p>${suggestion(d,t)}</p></div></div><footer>Starter targets are examples, not a personalized prescription. Set your own goals in settings.</footer>`;
['#log-meal','#add-food','#browse-food'].forEach(s=>{if($(s))$(s).onclick=()=>navigate('food');});$('#edit-targets').onclick=()=>navigate('settings');document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>checkin(b.dataset.check));document.querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>b.dataset.quest==='food'?navigate('food'):checkin(b.dataset.quest));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Remove this food from this day?'))editDay(d=>d.meals.splice(Number(b.dataset.delete),1));});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>portion(day().meals[Number(b.dataset.edit)].food,Number(b.dataset.edit)));}
function suggestion(d,t){if(!d.meals.length)return 'Start by logging what you normally eat. A useful pattern begins with an honest picture of your day.';if(t.missing.length)return 'Some foods have missing nutrient values. Check their labels before drawing conclusions from today’s totals.';if(t.protein<state.profile.targets.protein*.6)return 'Your logged protein is below your chosen target so far. Explore lentils, tofu, beans or plain Greek yogurt for your next meal.';if(d.sleep==null)return 'Add last night’s sleep to put your food and activity in context. Look for patterns across weeks, not one day.';return 'You’re building a useful record. Compare weekly averages and how you feel before changing your routine.';}
function checkin(type){if(type==='exercise'){modal(`<h2>Move in your own way</h2><p>Log what you did. Apple Health is not connected.</p><form id="check-form"><label class="field">Activity<select name="activity"><option>Strength training</option><option>Walking</option><option>Running</option><option>Cycling</option><option>Yoga</option><option>Swimming</option><option>Other exercise</option></select></label><label class="field">Minutes<input name="value" type="number" min="1" max="1440" required></label><button class="primary">Save activity</button></form>${day().exercise.map((e,i)=>`<div class="meal-row"><div class="meal-info">${esc(e.name)} · ${e.minutes} min</div><button class="text-button danger" data-remove-ex="${i}">Remove</button></div>`).join('')}`);document.querySelectorAll('[data-remove-ex]').forEach(b=>b.onclick=()=>{editDay(d=>d.exercise.splice(+b.dataset.removeEx,1));close();checkin(type);});}else{modal(`<h2>${type==='weight'?'Your daily check-in':'Rest is part of the work'}</h2><p>${type==='weight'?'A single reading can fluctuate. Your longer trend matters.':'Sleep duration for the night ending on the selected day.'}</p><form id="check-form"><label class="field">${type==='weight'?'Weight (kg)':'Sleep (hours)'}<input name="value" type="number" step="0.1" min="${type==='weight'?20:0}" max="${type==='weight'?400:24}" value="${day()[type]??''}" required></label><button class="primary">Save check-in</button></form>`);}$('#check-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v=Number(f.get('value'));editDay(d=>{if(type==='exercise')d.exercise.push({id:crypto.randomUUID(),name:f.get('activity'),minutes:v,source:'manual'});else d[type]=v;});close();notify('One small win, saved.');};}
function allFoods(){return [...state.customFoods,...state.recipes,...foods];}
function renderFood(){const matches=allFoods().filter(f=>(filter==='all'||(filter==='vegetarian'&&['plant','dairy'].includes(f.diet))||f.diet===filter||filter==='custom'&&String(f.id).startsWith('custom'))&&search.toLowerCase().split(' ').every(w=>f.name.toLowerCase().includes(w)));$('#content').innerHTML=`<div class="insight" style="margin-top:0"><span>◈</span><div><b>Your food, down to the gram.</b><p>${foods.length.toLocaleString()} USDA foods, source-linked portions, and space for your own recipes. Vegetarian first.</p></div></div><div class="toolbar"><input type="search" id="search" placeholder="Search lentils, yogurt, oats…" value="${esc(search)}" aria-label="Search foods"><select id="filter" aria-label="Diet filter"><option value="vegetarian">Vegetarian + dairy</option><option value="plant">Plant foods</option><option value="all">All foods, including meat & eggs</option><option value="custom">My custom foods</option></select><button class="secondary" id="custom">+ Custom food</button><button class="secondary" id="recipe">+ Build recipe</button></div><div class="section-heading"><h2>${search?'Search results':'Find your next meal'}</h2><p>${matches.length} matches</p></div><div class="food-grid">${matches.slice(0,60).map(f=>`<article class="food-card"><span class="tag">${esc(f.source)}</span><h3>${esc(f.name)}</h3><p>${f.nutrients.kcal==null?'—':n(f.nutrients.kcal)} kcal · ${f.nutrients.protein==null?'—':n(f.nutrients.protein)} g protein / 100 g</p><p>${esc(f.category||'Custom food')}</p><button class="secondary" data-food="${esc(f.id)}">+ Choose portion</button></article>`).join('')}</div>${!matches.length?'<div class="card meal-empty"><h3>No match yet</h3><p>Try a simpler name, switch to all foods, or add a food from its nutrition label.</p></div>':''}<footer>Showing up to 60 matches. Narrow your search for more. Diet tags are category-based; verify ingredients for strict vegetarian needs. Cooked and dry weights are different. <a href="https://fdc.nal.usda.gov/download-datasets/" target="_blank" rel="noopener">USDA source</a> · <a href="data-provenance.json" target="_blank">Data provenance</a></footer>`;$('#filter').value=filter;$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;renderFood();$('#search').focus();$('#search').setSelectionRange(pos,pos);};$('#filter').onchange=e=>{filter=e.target.value;renderFood();};document.querySelectorAll('[data-food]').forEach(b=>b.onclick=()=>portion(allFoods().find(f=>String(f.id)===b.dataset.food)));$('#custom').onclick=customFood;$('#recipe').onclick=recipeBuilder;}
function portion(food,index=null){const existing=index==null?null:day().meals[index];let grams=existing?.grams||100;modal(`<span class="tag">${esc(food.source)}</span><h2>${esc(food.name)}</h2><p>Choose the matching preparation and weigh your portion.</p><form id="portion-form"><label class="field">USDA serving conversion<select id="serving"><option value="100">100 g</option>${(food.portions||[]).map(p=>`<option value="${p.grams}">${esc(p.label)} (${n(p.grams)} g)</option>`).join('')}</select></label><label class="field">Quantity (grams)<div class="quantity"><button type="button" id="minus" aria-label="Reduce portion">−</button><input id="grams" type="number" min="0.1" max="10000" step="0.1" required value="${grams}"><button type="button" id="plus" aria-label="Increase portion">+</button></div></label><input id="quantity-range" aria-label="Adjust portion in grams" type="range" min="5" max="500" step="5" value="${grams}"><div class="nutrition-preview" id="nutrition-preview"></div><label class="field">Meal<select id="meal"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option></select></label><p class="hint">${food.sourceUrl?`<a href="${esc(food.sourceUrl)}" target="_blank" rel="noopener">View original nutrient record</a>`:'User-entered or recipe-calculated nutrition.'} · Values scale from 100 g. Missing values stay unknown.</p><button class="primary">${index==null?'Add to my day':'Save portion'}</button>${index==null?'<button type="button" id="add-ingredient" class="text-button full">Add to recipe instead</button>':''}</form>`);if(existing)$('#meal').value=existing.meal;const preview=()=>{grams=Number($('#grams').value);if(grams<=0||grams>10000)return;const t=scale(food.nutrients,grams);$('#nutrition-preview').innerHTML=keys.map(k=>`<span><b>${t[k]==null?'—':n(t[k])}${k==='kcal'?'':' g'}</b>${names[k]}</span>`).join('');$('#quantity-range').value=grams;};$('#grams').oninput=preview;$('#quantity-range').oninput=e=>{$('#grams').value=e.target.value;preview();};$('#serving').onchange=e=>{$('#grams').value=e.target.value;preview();};$('#minus').onclick=()=>{$('#grams').value=Math.max(.1,grams-10);preview();};$('#plus').onclick=()=>{$('#grams').value=Math.min(10000,grams+10);preview();};preview();$('#portion-form').onsubmit=e=>{e.preventDefault();const entry={id:existing?.id||crypto.randomUUID(),foodId:food.id,name:food.name,grams,meal:$('#meal').value,nutrients:scale(food.nutrients,grams),food:structuredClone(food)};editDay(d=>{if(index==null)d.meals.push(entry);else d.meals[index]=entry;});close();notify('Meal saved. Your daily totals are updated.');};if($('#add-ingredient'))$('#add-ingredient').onclick=()=>{if(!$('#portion-form').reportValidity())return;recipeDraft.push({food,grams});close();recipeBuilder();};}
function customFood(){modal(`<h2>A place for your favorites</h2><p>Copy the nutrition label. Enter values per 100 g; leave unknown nutrients blank.</p><form id="custom-form" class="form-grid"><label class="field wide">Food name<input name="name" required maxlength="180"></label><label class="field wide">Diet<select name="diet"><option value="dairy">Vegetarian with dairy</option><option value="plant">Plant-based</option><option value="other">Other / unknown</option></select></label>${keys.map(k=>`<label class="field">${names[k]} ${k==='kcal'?'(kcal)':'(g)'}<input type="number" name="${k}" min="0" max="${k==='kcal'?1000:100}" step="0.01"></label>`).join('')}<label class="field wide">Label / source note<input name="note" maxlength="300" placeholder="Brand and product, package label"></label><button class="primary wide">Save custom food</button></form>`);$('#custom-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),food={id:'custom-'+crypto.randomUUID(),name:f.get('name').trim(),diet:f.get('diet'),source:'Your nutrition label',sourceNote:f.get('note'),basisGrams:100,portions:[],nutrients:Object.fromEntries(keys.map(k=>[k,f.get(k)===''?null:Number(f.get(k))]))};if(!food.name)return;state.customFoods.push(food);persist();close();renderFood();portion(food);};}
function recipeBuilder(){modal(`<h2>Your recipe, your portions</h2><p>Choose ingredients from the food library, then enter the final cooked batch weight. Water changes weight, not the ingredient totals.</p>${recipeDraft.map((x,i)=>`<div class="meal-row"><div class="meal-info"><b>${esc(x.food.name)}</b><small>${x.grams} g</small></div><button class="text-button danger" data-remove-ingredient="${i}">×</button></div>`).join('')}<button class="secondary full" id="find-ingredient">+ Find an ingredient</button><form id="recipe-form"><label class="field">Recipe name<input name="name" required maxlength="180" placeholder="My dal, chana bowl, overnight oats…"></label><label class="field">Finished batch weight (g)<input name="weight" required type="number" min="1" max="20000" step="0.1"></label><button class="primary" ${recipeDraft.length?'':'disabled'}>Save recipe</button></form>`);$('#find-ingredient').onclick=()=>{close();navigate('food');notify('Choose a portion, then tap “Add to recipe instead”.');};document.querySelectorAll('[data-remove-ingredient]').forEach(b=>b.onclick=()=>{recipeDraft.splice(+b.dataset.removeIngredient,1);close();recipeBuilder();});$('#recipe-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),weight=Number(f.get('weight')),t=totals(recipeDraft.map(x=>({nutrients:scale(x.food.nutrients,x.grams)}))),food={id:'custom-recipe-'+crypto.randomUUID(),name:f.get('name').trim(),source:'Your recipe · calculated',diet:recipeDraft.some(x=>x.food.diet==='other')?'other':recipeDraft.some(x=>x.food.diet==='dairy')?'dairy':'plant',basisGrams:100,portions:[{label:'Full batch',grams:weight}],ingredients:structuredClone(recipeDraft),nutrients:Object.fromEntries(keys.map(k=>[k,t.missing.includes(k)?null:t[k]/weight*100]))};if(!food.name)return;state.recipes.push(food);recipeDraft=[];persist();close();renderFood();portion(food);};}
function renderProgress(){const rows=Object.entries(state.days).filter(([d])=>d<=date).sort(([a],[b])=>a.localeCompare(b));const weights=rows.filter(([,d])=>d.weight!=null).slice(-30),trend=weightTrend(state.days,date);const end=new Date(date+'T12:00:00'),start=new Date(end);start.setDate(start.getDate()-6);const prevEnd=new Date(start);prevEnd.setDate(prevEnd.getDate()-1);const prevStart=new Date(prevEnd);prevStart.setDate(prevStart.getDate()-6);const avg=averageWeight(state.days,localDate(start),date),prev=averageWeight(state.days,localDate(prevStart),localDate(prevEnd));let chart='<div class="meal-empty"><h3>Your story starts with a check-in.</h3><p>Log at least two weights to see a trend.</p></div>';if(weights.length>=2){const values=weights.map(([,d])=>d.weight),lo=Math.min(...values)-.5,hi=Math.max(...values)+.5;const first=new Date(weights[0][0]).getTime(),last=new Date(weights.at(-1)[0]).getTime();const points=weights.map(([d,v])=>`${20+(new Date(d).getTime()-first)/(last-first)*660},${190-(v.weight-lo)/(hi-lo)*160}`).join(' ');chart=`<svg class="chart" viewBox="0 0 700 220" role="img" aria-label="Body weight by date"><path d="M20 50H680M20 120H680M20 190H680" stroke="#e7ebe5"/><polyline points="${points}" fill="none" stroke="#7da64c" stroke-width="3" stroke-linejoin="round"/>${points.split(' ').map(p=>{const [x,y]=p.split(',');return `<circle cx="${x}" cy="${y}" r="5" fill="#bceb78" stroke="#547b30"/>`;}).join('')}</svg><div class="chart-labels"><span>${weights[0][0]} · ${n(values[0])} kg</span><span>${weights.at(-1)[0]} · ${n(values.at(-1))} kg</span></div>`;}
$('#content').innerHTML=`<div class="top-grid"><section class="card"><div class="card-head"><h2>The bigger picture</h2><span class="tag">Last 30 weigh-ins</span></div>${chart}</section><section class="card"><span class="eyebrow">7-DAY AVERAGE</span><div class="big-number">${avg.value==null?'—':n(avg.value)+' kg'}</div><p class="muted">${avg.count} readings in the selected week</p><p>${avg.count>=3&&prev.count>=3?`${n(avg.value-prev.value)} kg compared with the previous week`:'Log at least 3 weights in each week for a weekly comparison.'}</p><div class="insight"><div><b>Progress has more than one number.</b><p>Use trends alongside strength, energy, sleep and how you feel. Daily scale changes don’t tell the whole story.</p></div></div></section></div><div class="section-heading"><h2>Your daily record</h2><button class="text-button" id="export-progress">Export JSON</button></div><div class="card table-wrap"><table><thead><tr><th>Date</th><th>Weight</th><th>Calories</th><th>Protein</th><th>Fat</th><th>Carbs</th><th>Fiber</th><th>Sleep</th><th>Exercise</th></tr></thead><tbody>${rows.slice().reverse().map(([dt,d])=>{const t=totals(d.meals);return `<tr><td>${dt}</td><td>${d.weight==null?'—':n(d.weight)+' kg'}</td>${keys.map(k=>`<td>${d.meals.length?n(t[k])+(t.missing.includes(k)?'*':''):'—'}</td>`).join('')}<td>${d.sleep??'—'} h</td><td>${exerciseMinutes(d)} min</td></tr>`;}).join('')||'<tr><td colspan="9">No entries yet. Your first day is waiting.</td></tr>'}</tbody></table></div><footer>Blank days are not counted as zero. * Partial nutrient total. Nutrition data alone cannot establish why your weight changed.</footer>`;$('#export-progress').onclick=exportData;}
function exportData(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),schemaVersion:1,...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`sprout-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderSettings(){$('#content').innerHTML=`<div class="settings-grid"><section class="card"><h2>A plan that feels like you</h2><p>These are editable starting points. Use targets that suit your own needs and professional advice where appropriate.</p><form id="settings-form"><div class="form-grid"><label class="field">Your name<input name="name" value="${esc(state.profile.name)}" required maxlength="60"></label><label class="field">Focus<select name="goal"><option>Build strength & lose fat</option><option>Build strength</option><option>Gradual weight loss</option><option>Maintain & feel good</option></select></label>${Object.entries(state.profile.targets).map(([k,v])=>`<label class="field">${names[k]||({sleep:'Sleep (hours)',exercise:'Exercise (minutes)'}[k])}${['protein','fat','carbs','fiber'].includes(k)?' (g)':''}<input name="${k}" type="number" min="${k==='sleep'?1:1}" max="${k==='kcal'?10000:k==='sleep'?24:k==='exercise'?1440:1000}" step="${k==='sleep'?'.1':'1'}" required value="${v}"></label>`).join('')}</div><button class="primary">Save my goals</button></form></section><div><section class="card"><h2>Your data, in your hands</h2><p id="connection-copy">${window.SPROUT_CONFIG?.apiUrl?'Cloud endpoint configured. Sign in to sync.':'Google Cloud is not connected yet. Entries are stored on this device until you connect your new project.'}</p><div id="google-signin"></div><div class="toolbar"><button class="secondary" id="sync" ${token?'':'disabled'}>Sync to BigQuery</button><button class="text-button" id="restore" ${token?'':'disabled'}>Restore cloud copy</button>${token?'<button class="text-button" id="signout">Sign out</button>':''}</div><button class="secondary" id="export">Export my JSON</button><p class="hint">Cloud sign-in and storage will be restricted to your account. Export a backup before clearing browser data.</p></section><section class="card" style="margin-top:22px"><h2>Apple Health</h2><p>Manual exercise logging is ready. Direct Apple Health access requires an iPhone app or a separately configured bridge, so automatic sync is not connected.</p><button class="secondary" id="manual-exercise">Log an activity</button></section><section class="card" style="margin-top:22px"><h2>Know your food data</h2><p>The catalog uses USDA SR Legacy, April 2018, with original record links and gram conversions. Custom foods use your labels. Recipes use their ingredient totals.</p><p>IFCT is the appropriate Indian composition reference; a verified IFCT import is still pending. This catalog does not claim FSSAI certification.</p><a href="https://www.nin.res.in/ebooks/IFCT2017.pdf" target="_blank" rel="noopener">View ICMR–NIN reference</a></section></div></div>`;$('#settings-form [name=goal]').value=state.profile.goal;$('#settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.profile.name=f.get('name').trim();state.profile.goal=f.get('goal');for(const k of Object.keys(state.profile.targets))state.profile.targets[k]=Number(f.get(k));persist();render();notify('Your goals are saved.');};$('#export').onclick=exportData;$('#manual-exercise').onclick=()=>checkin('exercise');$('#sync').onclick=sync;$('#restore').onclick=restore;if($('#signout'))$('#signout').onclick=()=>{token=null;clearTimeout(syncTimer);google.accounts.id.disableAutoSelect();renderSettings();};initSignIn();}
function initSignIn(){const c=window.SPROUT_CONFIG;if(!c?.googleClientId)return;const init=()=>{google.accounts.id.initialize({client_id:c.googleClientId,callback:r=>{token=r.credential;renderSettings();notify('Signed in. You can now sync your diary.');}});google.accounts.id.renderButton($('#google-signin'),{theme:'outline',size:'large'});};if(window.google?.accounts)init();else if(!$('#google-script')){const s=document.createElement('script');s.id='google-script';s.src='https://accounts.google.com/gsi/client';s.onload=()=>{if(tab==='settings')init();};document.head.append(s);}}
async function api(path,options={}){const res=await fetch(window.SPROUT_CONFIG.apiUrl+path,{...options,headers:{'Content-Type':'application/json',Authorization:'Bearer '+token,...options.headers}});const data=await res.json();if(!res.ok){if(data.acceptedRevision){state.revision=data.acceptedRevision;localStorage.setItem('sprout-v1',JSON.stringify(state));}throw Error(data.error||'Cloud request failed. Your local entries are safe.');}return data;}
async function sync(){if(!token||syncing)return;syncing=true;if($('#sync'))$('#sync').disabled=true;const eventId=state.eventId||crypto.randomUUID(),snapshot=structuredClone(Object.fromEntries(['version','days','customFoods','recipes','profile'].map(k=>[k,state[k]])));state.eventId=eventId;try{const data=await api('/sync',{method:'POST',body:JSON.stringify({eventId,baseRevision:state.revision,state:snapshot})});state.revision=data.revision;if(state.eventId===eventId)state.pending=false;localStorage.setItem('sprout-v1',JSON.stringify(state));updateStatus();notify('Diary saved to your cloud and BigQuery.');}catch(e){notify(e.message);}finally{syncing=false;if($('#sync'))$('#sync').disabled=false;if(state.eventId!==eventId&&state.pending){clearTimeout(syncTimer);syncTimer=setTimeout(sync,1200);}}}
async function restore(){if(!confirm('Replace this device’s diary with your cloud copy? Export local JSON first if you have unsynced entries.'))return;try{const data=await api('/state');if(!data.state)return notify('No cloud diary exists yet.');state={...data.state,revision:data.revision,pending:false};localStorage.setItem('sprout-v1',JSON.stringify(state));render();notify('Cloud diary restored.');}catch(e){notify(e.message);}}
try{const res=await fetch('foods.json');if(!res.ok)throw Error();foods=await res.json();}catch{notify('The food library could not load. Custom food entry is still available.');}
render();
if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'read_daily_fitness_summary',description:'Read the currently selected day’s logged nutrition, sleep, weight and exercise without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object');return {date,...day(),totals:totals(day().meals),exerciseMinutes:exerciseMinutes(day())};}})).catch(()=>{});}
